namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0
        ? Math.Round((double)RatingSum / TotalRatings, 1)
        : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple, classic pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = [
                "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes evenly over the dough.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                "Top with fresh basil leaves and a drizzle of olive oil."
            ],
            TotalRatings = 12, RatingSum = 50
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = [
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp pancetta in a skillet over medium heat.",
                "Whisk eggs with grated Pecorino and plenty of black pepper.",
                "Toss hot pasta with pancetta, remove from heat.",
                "Quickly stir in the egg mixture, tossing constantly to create a creamy sauce.",
                "Serve immediately with extra cheese and pepper."
            ],
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin"],
            Steps = [
                "Marinate chicken pieces in yogurt, garam masala, and salt for 1 hour.",
                "Grill or broil chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger in a large pan.",
                "Add tomato sauce, cumin, and garam masala; simmer 15 minutes.",
                "Stir in cream and add the cooked chicken.",
                "Simmer for 10 minutes and serve over basmati rice."
            ],
            TotalRatings = 15, RatingSum = 68
        },
        new()
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Description = "Fragrant layered rice dish with mixed vegetables and spices.",
            Ingredients = ["Basmati rice", "Mixed vegetables", "Onion", "Yogurt", "Biryani masala", "Saffron", "Mint", "Cilantro", "Ghee"],
            Steps = [
                "Soak basmati rice for 30 minutes, then parboil until 70% cooked.",
                "Sauté sliced onions in ghee until golden brown.",
                "Add vegetables and biryani masala; cook for 5 minutes.",
                "Layer rice and vegetable mixture in a heavy-bottomed pot.",
                "Add saffron milk, mint, and cilantro between layers.",
                "Seal with foil and lid; cook on low heat for 25 minutes."
            ],
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = [
                "Brown ground beef in a skillet over medium-high heat.",
                "Drain fat and add taco seasoning with a splash of water.",
                "Simmer for 5 minutes until sauce thickens.",
                "Warm taco shells in the oven for 2 minutes.",
                "Fill shells with beef, then top with lettuce, tomato, cheese, sour cream, and salsa.",
                "Serve with lime wedges."
            ],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh, chunky avocado dip with lime and cilantro.",
            Ingredients = ["Avocados", "Lime juice", "Red onion", "Jalapeño", "Cilantro", "Tomato", "Salt"],
            Steps = [
                "Halve and pit ripe avocados; scoop into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in finely diced onion, jalapeño, and tomato.",
                "Add lime juice, chopped cilantro, and salt to taste.",
                "Serve immediately with tortilla chips."
            ],
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Classic chewy cookies loaded with chocolate chips.",
            Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla extract", "Flour", "Baking soda", "Salt", "Chocolate chips"],
            Steps = [
                "Cream butter with both sugars until light and fluffy.",
                "Beat in eggs one at a time, then add vanilla.",
                "Whisk flour, baking soda, and salt; gradually mix into wet ingredients.",
                "Fold in chocolate chips.",
                "Drop rounded tablespoons onto baking sheets.",
                "Bake at 375°F (190°C) for 9–11 minutes until edges are golden."
            ],
            TotalRatings = 20, RatingSum = 92
        },
        new()
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Description = "Classic Italian no-bake dessert with coffee-soaked ladyfingers.",
            Ingredients = ["Ladyfingers", "Espresso", "Mascarpone", "Eggs", "Sugar", "Cocoa powder", "Marsala wine"],
            Steps = [
                "Brew strong espresso and let it cool; mix with Marsala wine.",
                "Separate eggs; beat yolks with sugar until thick and pale.",
                "Fold mascarpone into the yolk mixture until smooth.",
                "Whip egg whites to stiff peaks and fold into mascarpone mixture.",
                "Dip ladyfingers briefly in espresso and layer in a dish.",
                "Spread mascarpone cream over ladyfingers; repeat layers.",
                "Refrigerate at least 4 hours; dust with cocoa powder before serving."
            ],
            TotalRatings = 14, RatingSum = 65
        }
    ];

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void Submit(RecipeSubmission submission)
    {
        var nextId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = nextId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        });
    }
}

