@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center gap-1">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                title="Rate @star stars">
            @(star <= DisplayRating ? "★" : "☆")
        </button>
    }
    @if (TotalRatings > 0)
    {
        <span class="ms-2 text-muted small">
            @AverageRating.ToString("0.0") / 5 (@TotalRatings ratings)
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success small">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int TotalRatings { get; set; }
    [Parameter] public EventCallback<int> OnRate { get; set; }

    private int? userRating;
    private bool submitted;

    private int DisplayRating => userRating ?? (int)Math.Round(AverageRating);

    private async Task Rate(int stars)
    {
        userRating = stars;
        submitted = true;
        await OnRate.InvokeAsync(stars);
    }
}

@page "/"
@using RecipeCommunity.Services

@inject RecipeService Recipes

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-4">
    <h1>🍽️ Recipe Community</h1>
    <p class="lead text-muted">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4">
    @foreach (var category in categories)
    {
        <div class="col">
            <a href="/category/@category" class="text-decoration-none">
                <div class="card h-100 shadow-sm border-0 text-center">
                    <div class="card-body">
                        <div class="display-4 mb-2">@GetEmoji(category)</div>
                        <h5 class="card-title">@category</h5>
                        <p class="card-text text-muted">
                            @Recipes.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-5">
    <h4>Have a recipe to share?</h4>
    <a href="/submit" class="btn btn-success btn-lg mt-2">📝 Submit a Recipe</a>
</div>

@code {
    private IReadOnlyList<string> categories = [];

    protected override void OnInitialized()
    {
        categories = Recipes.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h2>@CategoryName Recipes</h2>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">
                            <a href="/recipe/@recipe.Id">@recipe.Title</a>
                        </h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <span class="text-muted small ms-1">(@recipe.AverageRating.ToString("0.0"))</span>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnInitialized()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared

@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h2>@recipe.Title</h2>
    <p class="lead text-muted">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id"
                AverageRating="recipe.AverageRating"
                TotalRatings="recipe.TotalRatings"
                OnRate="HandleRating" />

    <hr />

    <div class="row">
        <div class="col-md-4">
            <h4>🥘 Ingredients</h4>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>

        <div class="col-md-8">
            <h4>📋 Steps</h4>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = Recipes.GetById(Id);
    }

    private void HandleRating(int stars)
    {
        Recipes.AddRating(Id, stars);
        recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService Recipes

<PageTitle>Submit a Recipe</PageTitle>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added.
        <a href="/">Browse recipes</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" class="mt-3">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5"
                           placeholder="One ingredient per line" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="6"
                           placeholder="One step per line" />
        </div>

        <button type="submit" class="btn btn-primary"
                disabled="@(!IsValid)">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission model = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(model.Title) &&
        !string.IsNullOrWhiteSpace(model.Category) &&
        !string.IsNullOrWhiteSpace(model.Ingredients) &&
        !string.IsNullOrWhiteSpace(model.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        Recipes.Submit(model);
        submitted = true;
    }
}

